 std::vector<FreeSourceView> freeSources()const{std::vector<FreeSourceView> result;if(!freeActive())return result;const auto& data=*doc_.layer().freeTiles;const auto& resources=doc_.timeline().state().tilesets;if(!data.sources.empty()){for(const auto& source:data.sources){auto set=std::find_if(resources.begin(),resources.end(),[&](const auto& t){return t.id==source.tilesetId;});if(set!=resources.end()&&!set->tileIds.empty())result.push_back({source.id,set->id,set->tileIds.front()});}}else{auto set=std::find_if(resources.begin(),resources.end(),[&](const auto& t){return t.id==data.legacyTilesetId;});if(set!=resources.end())for(const auto& id:set->tileIds)result.push_back({id,set->id,id});}return result;}
