 bool pointerMove(ui::MouseMessage& m){if(gesture_==Gesture::None)return false;if(!grid_->hasCapture()||!grid_->isVisible()||!grid_->isEnabled()){cancelGesture();return true;}last_=m.position();if(gesture_==Gesture::Range)updateRange(last_);else if(gesture_==Gesture::Move&&(std::abs(last_.x-start_.x)>=uiScale||std::abs(last_.y-start_.y)>=uiScale)){if(auto t=current())if(auto target=slotAt(last_,true))preview_=tiles::repositionSlots(tiles::normalizedSlots(*t),selected_,*target,moveAnchor_,columns());grid_->invalidate();}return true;}
