 void paintGrid(ui::Graphics& g,gfx::Rect physical){if(freeActive()){paintFreeGrid(g,physical);return;}clampScroll();{UiPaintScale scale(g);auto r=uiLogical(physical);g.fillRect(skin_["panel"],r);const auto t=current();if(!t)return;const auto layout=slots();const int cols=columns(),page=pageRows();const auto roles=doc_.tileSelection();for(int row=0;row<=page;++row)for(int col=0;col<cols;++col){auto i=std::size_t(row+scroll_)*cols+col;if(i>=layout.size()||!layout[i])continue;const auto& id=*layout[i];gfx::Rect cell(r.x+col*42,r.y+row*42,40,40);if(roles.tilesetId==t->id&&roles.primary==id)g.fillRect(skin_["accent"],cell);else if(roles.tilesetId==t->id&&roles.secondary==id)g.fillRect(skin_["muted"],cell);for(int y=2;y<38;y+=6)for(int x=2;x<38;x+=6)g.fillRect(skin_[((x/6+y/6)%2)?"checkerA":"checkerB"],{cell.x+x,cell.y+y,6,6});const auto key=t->id+"/"+id;auto& image=images_[key];if(!image){auto index=tiles::Index(*t).find(id);if(!index)continue;auto pixels=tiles::readTile(*t,*index);image=os::instance()->makeRgbaSurface(t->tileWidth,t->tileHeight);if(!image)continue;uploadRgbaRegion(*image,pixels.data(),t->tileWidth,t->tileHeight,t->tileWidth);}const double z=std::min(36.0/t->tileWidth,36.0/t->tileHeight);const int w=std::max(1,int(t->tileWidth*z)),h=std::max(1,int(t->tileHeight*z));ui::Paint paint;paint.blendMode(os::BlendMode::SrcOver);g.drawSurface(image.get(),{0,0,t->tileWidth,t->tileHeight},{cell.x+(40-w)/2,cell.y+(40-h)/2,w,h},os::Sampling(os::Sampling::Filter::Nearest),&paint);}}paintSelection(g);}
